begin;
create extension if not exists pgtap;
select plan(67);

select has_table('public','acquisition_classification_options','options table exists');
select has_table('public','classification_rules','rules table exists');
select has_table('public','acquisition_line_classifications','classification table exists');
select ok((select relrowsecurity from pg_class where oid='public.acquisition_classification_options'::regclass),'options RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.classification_rules'::regclass),'rules RLS enabled');
select ok((select relrowsecurity from pg_class where oid='public.acquisition_line_classifications'::regclass),'classifications RLS enabled');
select col_type_is('public','acquisition_classification_options','id','uuid','option id uuid');
select col_type_is('public','classification_rules','version','integer','rule version int');
select col_type_is('public','acquisition_line_classifications','evidence','jsonb','evidence jsonb');

insert into auth.users (id,email) values ('10000000-0000-4000-8000-000000000001','a@example.test'),('20000000-0000-4000-8000-000000000002','b@example.test') on conflict do nothing;
insert into public.workspaces (id,name,created_by) values ('10000000-1000-4000-8000-000000000001','A','10000000-0000-4000-8000-000000000001'),('20000000-2000-4000-8000-000000000002','B','20000000-0000-4000-8000-000000000002');

select is((select count(*)::int from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001'),10,'workspace A gets ten options');
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002'),10,'workspace B gets ten options');
select results_eq($$select key,label from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' order by display_order$$,$$values ('slab','Slab'),('single','Single'),('sealed','Sealed'),('sneakers','Sneakers'),('apparel','Apparel'),('accessories','Accessories'),('electronics','Electronics'),('collectibles','Collectibles'),('other','Other'),('unreviewed','Unreviewed')$$,'default keys and labels match D-6');
select ok((select bool_and(public_id ~ '^RV-ACOPT-[A-Z0-9]{12}$') from public.acquisition_classification_options),'option public ids match prefix');
select app.seed_acquisition_classification_defaults('10000000-1000-4000-8000-000000000001');
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001'),10,'seeding is idempotent');
insert into public.acquisition_classification_options(workspace_id,key,label,display_order,active,origin,created_by) values('10000000-1000-4000-8000-000000000001','custom_type','Custom Type',200,true,'owner_created','10000000-0000-4000-8000-000000000001');
select pass('owner-created extra option supported');
select is((select count(*)::int from pg_type where typname in ('slab','single','sealed','unreviewed','acquisition_classification_option')) ,0,'classification is not a PostgreSQL enum');
select throws_ok($$insert into public.acquisition_classification_options(workspace_id,key,label,display_order,active,origin,created_by) values('10000000-1000-4000-8000-000000000001','slab','Slab 2',201,true,'owner_created','10000000-0000-4000-8000-000000000001')$$,'23505',null,'duplicate key rejected');
insert into public.acquisition_classification_options(workspace_id,key,label,display_order,active,origin,created_by) values('20000000-2000-4000-8000-000000000002','custom_type','Custom Type B',200,true,'owner_created','20000000-0000-4000-8000-000000000002');
select pass('same semantic key in separate workspace allowed');
select throws_ok($$insert into public.classification_rules(workspace_id,logical_key,rule_family,matcher_kind,match_field,exact_value,target_classification_option_id,precedence,version,status,rationale,source) select '10000000-1000-4000-8000-000000000001','x','business_vertical_mapping','exact','business_vertical','x',id,1,1,'active','x','owner_created' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='slab'$$,'23503',null,'cross-workspace option target rejected');

select is((select count(*)::int from public.classification_rules where workspace_id='10000000-1000-4000-8000-000000000001'),21,'initial rule rows exist');
select ok((select bool_and(public_id ~ '^RV-CRULE-[A-Z0-9]{12}$') from public.classification_rules),'rule public ids match prefix');
select is((select o.key from public.classification_rules r join public.acquisition_classification_options o on o.id=r.target_classification_option_id where r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:topshelfcollects'),'single','topshelfcollects targets Single');
select is((select o.key from public.classification_rules r join public.acquisition_classification_options o on o.id=r.target_classification_option_id where r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:loosepacks'),'sealed','loosepacks targets Sealed');
select is((select o.key from public.classification_rules r join public.acquisition_classification_options o on o.id=r.target_classification_option_id where r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:findsfordays'),'single','findsfordays targets Single');
select ok((select bool_and(char_length(btrim(rationale))>0 and rationale ilike '%fallback%' and rationale ilike '%must not override%') from public.classification_rules where rule_family='seller_specialization'),'seller rules have fallback rationale');
select ok((select bool_and(source='legacy_classifier_v5' and version=5) from public.classification_rules where workspace_id='10000000-1000-4000-8000-000000000001'),'legacy provenance/version recorded');
select ok(exists(select 1 from public.classification_rules where rule_family='strong_mystery_pattern' and pattern like '%mystery%'),'strong mystery data exists');
select ok(exists(select 1 from public.classification_rules where pattern like '%psa%' or pattern like '%slabs%'),'slab/grader data exists');
select ok(exists(select 1 from public.classification_rules where pattern like '%booster pack%'),'sealed data exists');
select ok(exists(select 1 from public.classification_rules where pattern like '%near mint%'),'single data exists');
select is((select count(*)::int from public.classification_rules where rule_family='business_vertical_mapping' and workspace_id='10000000-1000-4000-8000-000000000001'),8,'business vertical rules exist');
select is((select count(*)::int from (select precedence from public.classification_rules where workspace_id='10000000-1000-4000-8000-000000000001' group by precedence having count(*)>1) d),0,'precedence deterministic');
select throws_ok($$insert into public.classification_rules(workspace_id,logical_key,rule_family,matcher_kind,match_field,exact_value,target_classification_option_id,precedence,version,status,rationale,source) select workspace_id,'seller:topshelfcollects','seller_specialization','exact','seller_normalized','topshelfcollects',target_classification_option_id,999,5,'active','dupe','legacy_classifier_v5' from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001' limit 1$$,'23505',null,'duplicate active logical version rejected');
insert into public.classification_rules(workspace_id,logical_key,rule_family,matcher_kind,match_field,exact_value,target_classification_option_id,precedence,version,status,rationale,source) select workspace_id,'seller:topshelfcollects','seller_specialization','exact','seller_normalized','topshelfcollects',target_classification_option_id,999,6,'retired','historical version coexists','legacy_classifier_v5' from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001' limit 1;
select pass('new historical version can coexist');
select throws_ok($$update public.classification_rules set rationale='changed' where logical_key='seller:loosepacks' and workspace_id='10000000-1000-4000-8000-000000000001'$$,'2F000',null,'rule semantic fields immutable');
select throws_ok($$delete from public.classification_rules where logical_key='seller:findsfordays' and workspace_id='10000000-1000-4000-8000-000000000001'$$,'2F000',null,'rules cannot be deleted');
select ok(not has_table_privilege('anon','public.classification_rules','SELECT'),'anonymous rules denied');

-- Minimal governed acquisition line fixtures.
insert into public.source_systems(id,workspace_id,public_id,key,name,created_by) values('11000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','RV-SRC-A','src-a','Src A','10000000-0000-4000-8000-000000000001'),('22000000-0000-4000-8000-000000000002','20000000-2000-4000-8000-000000000002','RV-SRC-B','src-b','Src B','20000000-0000-4000-8000-000000000002');
insert into public.import_jobs(id,workspace_id,public_id,source_system_id,source_label,file_sha256,content_sha256,parser_version,mapping_version,idempotency_key,status,status_changed_at,source_row_count,accepted_row_count,issue_row_count,source_totals,actor_user_id,actor_process) values('12000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','RV-IMP-A','11000000-0000-4000-8000-000000000001','a',repeat('a',64),repeat('b',64),'1.0.0','1.0.0','idem-a','committed',now(),1,1,0,'{}','10000000-0000-4000-8000-000000000001','test'),('22000000-0000-4000-8000-000000000003','20000000-2000-4000-8000-000000000002','RV-IMP-B','22000000-0000-4000-8000-000000000002','b',repeat('c',64),repeat('d',64),'1.0.0','1.0.0','idem-b','committed',now(),1,1,0,'{}','20000000-0000-4000-8000-000000000002','test');
insert into public.source_records(id,workspace_id,import_job_id,source_row_index,source_row_key,raw_payload,normalized_hash,parse_status,parser_output,parser_version,mapping_version,errors,warnings) values('13000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001',1,'a','{}',repeat('e',64),'accepted','{}','1.0.0','1.0.0','[]','[]'),('23000000-0000-4000-8000-000000000002','20000000-2000-4000-8000-000000000002','22000000-0000-4000-8000-000000000003',1,'b','{}',repeat('f',64),'accepted','{}','1.0.0','1.0.0','[]','[]');
insert into public.channels(id,workspace_id,public_id,name,kind,created_by) values('14000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','RV-CH-AAAAAA','A','manual','10000000-0000-4000-8000-000000000001'),('24000000-0000-4000-8000-000000000002','20000000-2000-4000-8000-000000000002','RV-CH-BBBBBB','B','manual','20000000-0000-4000-8000-000000000002');
insert into public.acquisition_import_jobs(id,workspace_id,channel_id,source_import_job_id,idempotency_key,mode,status,expected_line_count,mapping_version,plan_sha256,committed_orders,committed_lots,committed_line_items,committed_cost_components,committed_unresolved_supplier_candidates,committed_unresolved_cost_components,actor_user_id,actor_process) values('15000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','14000000-0000-4000-8000-000000000001','12000000-0000-4000-8000-000000000001','acq-a','commit','committed',1,'1.0.0',repeat('1',64),1,0,1,0,0,0,'10000000-0000-4000-8000-000000000001','test'),('25000000-0000-4000-8000-000000000002','20000000-2000-4000-8000-000000000002','24000000-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000003','acq-b','commit','committed',1,'1.0.0',repeat('2',64),1,0,1,0,0,0,'20000000-0000-4000-8000-000000000002','test');
insert into public.acquisition_line_items(id,workspace_id,public_id,source_system_id,source_record_id,acquisition_import_job_id,quantity,created_by_process) values('16000000-0000-4000-8000-000000000001','10000000-1000-4000-8000-000000000001','LINE-A','11000000-0000-4000-8000-000000000001','13000000-0000-4000-8000-000000000001','15000000-0000-4000-8000-000000000001',1,'test'),('26000000-0000-4000-8000-000000000002','20000000-2000-4000-8000-000000000002','LINE-B','22000000-0000-4000-8000-000000000002','23000000-0000-4000-8000-000000000002','25000000-0000-4000-8000-000000000002',1,'test');

insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select r.workspace_id,'16000000-0000-4000-8000-000000000001',r.target_classification_option_id,'rule',r.id,r.version,0.9000,'{"matched":"seller"}','legacy_classifier_v5' from public.classification_rules r where r.workspace_id='10000000-1000-4000-8000-000000000001' and r.logical_key='seller:topshelfcollects';
select is((select count(*)::int from public.acquisition_line_classifications),1,'classification can reference same-workspace governed line');
select ok((select bool_and(public_id ~ '^RV-ACLS-[A-Z0-9]{12}$') from public.acquisition_line_classifications),'classification public ids match prefix');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '10000000-1000-4000-8000-000000000001','26000000-0000-4000-8000-000000000002',target_classification_option_id,'rule',id,version,0.9,'{}','legacy_classifier_v5' from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001' limit 1$$,'23503',null,'cross-workspace acquisition line rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '10000000-1000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options o, public.classification_rules r where o.workspace_id='20000000-2000-4000-8000-000000000002' and o.key='single' and r.logical_key='seller:topshelfcollects' and r.workspace_id='10000000-1000-4000-8000-000000000001' limit 1$$,'23503',null,'cross-workspace option rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '10000000-1000-4000-8000-000000000001','16000000-0000-4000-8000-000000000001',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options o, public.classification_rules r where o.workspace_id='10000000-1000-4000-8000-000000000001' and o.key='single' and r.workspace_id='20000000-2000-4000-8000-000000000002' limit 1$$,'23503',null,'cross-workspace rule rejected');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,system_provenance) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'rule',0.9,'{}','legacy_classifier_v5' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='single'$$,'23514',null,'rule method requires rule');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'owner_override',0.9,'{}' from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='single'$$,'23514',null,'owner override requires actor');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by) select workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',1.5,'{}','20000000-0000-4000-8000-000000000002' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'confidence bounded');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by) select workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',0.9,'[]','20000000-0000-4000-8000-000000000002' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'evidence must be object');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select r.workspace_id,'16000000-0000-4000-8000-000000000001',r.target_classification_option_id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.classification_rules r where r.logical_key='seller:findsfordays' and r.workspace_id='10000000-1000-4000-8000-000000000001'$$,'23505',null,'only one current classification per line');
insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select workspace_id,'16000000-0000-4000-8000-000000000001',id,'owner_override',1,'{"override":true}','10000000-0000-4000-8000-000000000001',(select id from public.acquisition_line_classifications limit 1) from public.acquisition_classification_options where workspace_id='10000000-1000-4000-8000-000000000001' and key='sealed';
select is((select count(*)::int from public.acquisition_line_classifications where acquisition_line_item_id='16000000-0000-4000-8000-000000000001'),2,'second decision can supersede first and history remains');
select throws_ok($$update public.acquisition_line_classifications set evidence='{"changed":true}' where id=(select id from public.acquisition_line_classifications limit 1)$$,'2F000',null,'classification semantic fields immutable');
select throws_ok($$delete from public.acquisition_line_classifications where id=(select id from public.acquisition_line_classifications limit 1)$$,'2F000',null,'classifications cannot be deleted');
select throws_ok($$insert into public.acquisition_line_classifications(id,workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select '17000000-0000-4000-8000-000000000001',workspace_id,'26000000-0000-4000-8000-000000000002',id,'owner_override',1,'{}','20000000-0000-4000-8000-000000000002','17000000-0000-4000-8000-000000000001' from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23514',null,'row cannot supersede itself');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,confidence,evidence,created_by,supersedes_classification_id) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',id,'owner_override',1,'{}','20000000-0000-4000-8000-000000000002',(select id from public.acquisition_line_classifications where workspace_id='10000000-1000-4000-8000-000000000001' limit 1) from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002' and key='single'$$,'23503',null,'supersession cannot cross workspaces');
select throws_ok($$insert into public.acquisition_line_classifications(workspace_id,acquisition_line_item_id,classification_option_id,method,rule_id,rule_version,confidence,evidence,system_provenance) select '20000000-2000-4000-8000-000000000002','26000000-0000-4000-8000-000000000002',o.id,'rule',r.id,r.version,0.9,'{}','legacy_classifier_v5' from public.classification_rules r join public.acquisition_classification_options o on o.workspace_id=r.workspace_id where r.workspace_id='20000000-2000-4000-8000-000000000002' and r.logical_key='seller:loosepacks' and o.key='single'$$,'23514',null,'rule target cannot contradict classification');
select is((select count(*)::int from public.classification_rules where logical_key='seller:topshelfcollects' and workspace_id='10000000-1000-4000-8000-000000000001'),2,'rule history intact after version insert');

select ok(has_table_privilege('authenticated','public.acquisition_classification_options','SELECT'),'authenticated may read options');
select ok(not has_table_privilege('authenticated','public.acquisition_classification_options','INSERT'),'authenticated lacks option insert');
select ok(not has_table_privilege('authenticated','public.classification_rules','UPDATE'),'authenticated lacks rule update');
select ok(not has_table_privilege('authenticated','public.acquisition_line_classifications','DELETE'),'authenticated lacks classification delete');
select ok(not has_table_privilege('anon','public.acquisition_classification_options','SELECT'),'anon lacks option select');
select ok(not has_table_privilege('anon','public.classification_rules','SELECT'),'anon lacks rule select');
select ok(not has_table_privilege('anon','public.acquisition_line_classifications','SELECT'),'anon lacks classification select');

select set_config('request.jwt.claims', json_build_object('sub','10000000-0000-4000-8000-000000000001','role','authenticated')::text, true); set local role authenticated;
select is((select count(*)::int from public.acquisition_classification_options where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B options');
select is((select count(*)::int from public.classification_rules where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B rules');
select is((select count(*)::int from public.acquisition_line_classifications where workspace_id='20000000-2000-4000-8000-000000000002'),0,'workspace A cannot read B classifications');
reset role;

select * from finish();
rollback;
